  doc <- pdf_doc_open(fixture_path("shapes"))
  on.exit(pdf_doc_close(doc), add = TRUE)
  expect_error(
    pdf_render_page_with_matrix(doc, c(1, 2),
      pixel_width = 100,
      pixel_height = 100
    ),
    "Assertion on"
  )
  expect_error(
    pdf_render_page_with_matrix(doc, rep(NA_real_, 6),
      pixel_width = 100,
      pixel_height = 100
    ),
    "Assertion on"
  )
  expect_error(
    pdf_render_page_with_matrix(doc, c(1, 0, 0, 1, 0, 0),
      pixel_width = 0,
      pixel_height = 100
    ),
    "Assertion on"
  )
  expect_error(
    pdf_render_page_with_matrix(doc, c(1, 0, 0, 1, 0, 0),
      pixel_width = 100,
      pixel_height = 100,
      clip_rect = c(1, 2, 3)
    ),
    "Assertion on"
  )
  # matrix() shape coercion paths.
  expect_silent({
    bmp <- pdf_render_page_with_matrix(doc,
      matrix(c(1, 0, 0, 1, 0, 0), nrow = 3, ncol = 2, byrow = TRUE),
      pixel_width = 50, pixel_height = 50
